action.mutation:
mutation CreatePick($payload: [PickCreatePayloadInput!]!) {
  mutation: createPick(payload: $payload) {
    id
    number
  }
}

mutation DeletePick($payload: [PickDeletePayloadInput!]!) {
  mutation: deletePick(payload: $payload) { 
    id
    number
  }
}

dataTransform.transform:
(
  /* INITIAL DATA LOAD TABLE 1 */
  [
    $.edges.node ~> | $ | {
      "userName": 
        $evalHandlebarsTemplate("{{firstName}} {{lastName}}", {"firstName": user.firstName, "lastName": user.lastName}),
      "invalidated": pickSteps.edges.node.affectedNonConformances.total ? true,
      "offScript": pickSteps.edges.node.causeNonConformances.total ? true,
      "icon": pickSteps.edges.node.affectedNonConformances.total ? "triangle-exclamation" : "na" } |
  ]
)

dataSubscription.valueTransform:
(
  /* DATA CHANGE TABLE 1 */
  $affectedId := event.body.value.after.affectedPickStepId;
  $causedId := event.body.value.after.causePickStepId;

  [
    data ~> | $ | {
      "invalidated": $affectedId in pickSteps.edges.node.id ? true : false,
      "offScript": $causedId in pickSteps.edges.node.id ? true : false,
      "icon": $affectedId in pickSteps.edges.node.id ? "triangle-exclamation" : "na" } |
  ]
)

query.query:
query ($filter: PickOrderLineWhereInput!){
  pickOrderLine( where: $filter){
    edges{
      node{
        id
        pickOrder{
          id
                 }
        product{ 
          id 
          code
          defaultQuantityUnitId
        }
        requiredQuantity: quantity{ 
          value 
          unitId
          unit{
            id
            code
          }
        }

        assignedQuantity: pickSteps{
          edges{
            node{
              quantity{
                _aggregate{
                  value{
                    sum
                  }
                }
              }
            }
          }
        }

        fulfilledQuantity: pickSteps(
          where:  {
             pickStepStatusId:  {
                _in: ["picked", "completed"] 
             }
          }
        ){
          edges{
            node{
              quantity{
                _aggregate{
                  value{
                    sum
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}
